describe('Virus Scan Status for Uploaded Files', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display virus scan status for uploaded file', () => {
    // Intercept the API call to upload file
    cy.intercept('POST', '/api/upload/file', {
      statusCode: 200,
      body: {
        fileId: '12345',
        fileSize: '1024KB',
        virusScanStatus: 'Pending',
        virusScanResult: 'Not detected',
        uploadDate: '2023-04-01T12:00:00Z'
      }
    }).as('uploadFile');

    // Upload a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf', { force: true });
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the upload API call
    cy.wait('@uploadFile');

    // Verify virus scan status is displayed
    cy.get('[data-testid="virus-scan-status"]').should('be.visible');
    cy.get('[data-testid="virus-scan-status"]').should('contain', 'Pending');

    // Verify virus scan result is displayed
    cy.get('[data-testid="virus-scan-result"]').should('be.visible');
    cy.get('[data-testid="virus-scan-result"]').should('contain', 'Not detected');

    // Verify file details are displayed
    cy.get('[data-testid="file-name"]').should('contain', 'test-file.pdf');
    cy.get('[data-testid="file-size"]').should('contain', '1024KB');

    // Verify upload date is displayed
    cy.get('[data-testid="upload-date"]').should('be.visible');
    cy.get('[data-testid="upload-date"]').should('contain', '2023-04-01');
  });

  it('should display error when virus scan fails', () => {
    // Intercept the API call to upload file with error
    cy.intercept('POST', '/api/upload/file', {
      statusCode: 500,
      body: {
        error: 'Internal server error',
        fileId: null
      }
    }).as('uploadFileError');

    // Upload a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf', { force: true });
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the failed upload API call
    cy.wait('@uploadFileError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Upload failed');

    // Verify virus scan status is not displayed
    cy.get('[data-testid="virus-scan-status"]').should('not.exist');

    // Verify file details are not displayed
    cy.get('[data-testid="file-name"]').should('not.exist');
    cy.get('[data-testid="file-size"]').should('not.exist');

    // Verify retry button is visible
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });
});
